class Car:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year

    def is_antique(self):
        return self.year <= 1950

    def __repr__(self):
        return f"{self.year} {self.make} {self.model}"

    @classmethod
    def from_string(cls, text):
        car_regex = classmethod(r'^(\d{4}) (\w+) (\w+)')
        match = car_regex.match(text)
        if match:
            return cls(*match.groups())

    def __str__(self):
        return f"{self.year} {self.make} {self.model}"

car = Car.from_string('1969 Chevrolet Camaro')
print(car.is_antique())

